insert into catalog_engines (code, alt_codes, display_name, displacement_cc, power_kw, fuel_type, torque_nm, cylinders, emission_standard, timing_type, engine_oil_capacity_liters, timing_replacement_km)
values
  ('DXDB', '{}', '1.5 eTSI 110kW', 1498, 110, 'petrol', 250, 'L4', 'Euro6e', 'belt', 4.3, 120000),
  ('DNPA', '{}', null, null, 150, 'petrol', null, null, 'Euro6e', null, null, null),
  ('DNFE', '{}', '2.0 TSI 195kW', 1984, 195, 'petrol', 400, 'L4', 'Euro6e', 'chain', 5.7, null),
  ('DXNM', '{}', '2.0 TDI 142kW', 1968, 142, 'diesel', 400, 'L4', 'Euro6e', 'belt', 4.7, 210000)
on conflict (code, power_kw) do nothing;

-- ════════════════════════════════════════════════════════════
-- 6. PHASE_BODY_DIMENSIONS
--    1 row(s), one per (phase x body).
-- ════════════════════════════════════════════════════════════

with dim_values (phase_label, body_type, length_mm, width_mm, height_mm, ground_clearance_mm, curb_weight_kg, boot_capacity_liters, boot_max_liters, gross_vehicle_weight_kg, payload_kg, fuel_tank_capacity_liters, seats_count) as (
  values
    ('Pre-facelift'::text, 'Estate'::text, 4917::integer, 1849::integer, 1497::integer, 140::integer, 1572::integer, 690::integer, 1920::integer, 2170::integer, 598::integer, 66::numeric, 5::integer)
),
phase_lookup as (
  select cp.id, cp.phase_label
  from catalog_phases cp
  join catalog_models cm on cm.id = cp.model_id
  join catalog_brands cb on cb.id = cm.brand_id
  where cb.name = 'Volkswagen' and cm.name = 'Passat' and cp.generation_code = 'CJ'
)
insert into phase_body_dimensions (phase_id, body_type_id, length_mm, width_mm, height_mm, ground_clearance_mm, curb_weight_kg, boot_capacity_liters, boot_max_liters, gross_vehicle_weight_kg, payload_kg, fuel_tank_capacity_liters, seats_count)
select p.id, bt.id, v.length_mm, v.width_mm, v.height_mm, v.ground_clearance_mm, v.curb_weight_kg, v.boot_capacity_liters, v.boot_max_liters, v.gross_vehicle_weight_kg, v.payload_kg, v.fuel_tank_capacity_liters, v.seats_count
from dim_values v
join phase_lookup p on p.phase_label = v.phase_label
join catalog_body_types bt on bt.name = v.body_type
on conflict (phase_id, body_type_id) do nothing;

-- ════════════════════════════════════════════════════════════
-- 7. VEHICLE CONFIGURATIONS
--    5 row(s), one per marked 'x' cell. dt = null means no AWD system.
-- ════════════════════════════════════════════════════════════

with
  phase_lookup as (
    select cp.id, cp.phase_label
    from catalog_phases cp
    join catalog_models cm on cm.id = cp.model_id
    join catalog_brands cb on cb.id = cm.brand_id
    where cb.name = 'Volkswagen' and cm.name = 'Passat' and cp.generation_code = 'CJ'
  ),
  body_lookup as (
    select id, name from catalog_body_types
  ),
  engine_lookup as (
    select id, code, power_kw from catalog_engines
  ),
  unit_lookup as (
    select id, code, alt_codes from transmission_units
  ),
  dt_lookup as (
    select id, code from drivetrain_systems where code in ('haldex_gen6')
  ),
  configs (phase_label, body_name, engine_code, engine_power_kw, unit_code, dt_code) as (
    values
      ('Pre-facelift'::text, 'Estate'::text, 'DXDB'::text, 110::integer, 'DQ381'::text, null::text),
      ('Pre-facelift'::text, 'Estate'::text, 'DNPA'::text, 150::integer, 'DQ381'::text, null::text),
      ('Pre-facelift'::text, 'Estate'::text, 'DNFE'::text, 195::integer, 'DQ381'::text, 'haldex_gen6'::text),
      ('Pre-facelift'::text, 'Estate'::text, 'DFFA'::text, 110::integer, 'DQ381'::text, null::text),
      ('Pre-facelift'::text, 'Estate'::text, 'DXNM'::text, 142::integer, 'DQ381'::text, 'haldex_gen6'::text)
  )
insert into catalog_vehicle_configurations (phase_id, body_type_id, engine_id, unit_id, drivetrain_id)
select p.id, b.id, e.id, u.id, d.id
from configs c
join phase_lookup p on p.phase_label = c.phase_label
join body_lookup b on b.name = c.body_name
join engine_lookup e on e.code = c.engine_code and e.power_kw = c.engine_power_kw
join unit_lookup u on u.code = c.unit_code or c.unit_code = any(u.alt_codes)
left join dt_lookup d on d.code = c.dt_code
on conflict (
  phase_id, body_type_id, engine_id, unit_id,
  coalesce(drivetrain_id, '00000000-0000-0000-0000-000000000000'::uuid)
) do nothing;

-- ════════════════════════════════════════════════════════════
-- 8. TRIMS
--    4 row(s).
-- ════════════════════════════════════════════════════════════

insert into catalog_trims (phase_id, name, tier)
select p.id, v.name, v.tier
from (
  values
    ('Pre-facelift'::text, 'Passat'::text, 1::integer),
    ('Pre-facelift'::text, 'Business'::text, 2::integer),
    ('Pre-facelift'::text, 'Elegance'::text, 3::integer),
    ('Pre-facelift'::text, 'R-Line'::text, 3::integer)
) as v(phase_label, name, tier)
join (
  select cp.id, cp.phase_label
  from catalog_phases cp
  join catalog_models cm on cm.id = cp.model_id
  join catalog_brands cb on cb.id = cm.brand_id
  where cb.name = 'Volkswagen' and cm.name = 'Passat' and cp.generation_code = 'CJ'
) as p on p.phase_label = v.phase_label
where not exists (
  select 1 from catalog_trims ct where ct.phase_id = p.id and ct.name = v.name
);

-- ════════════════════════════════════════════════════════════
-- 9. TRIM FEATURES
--    18 row(s).
-- ════════════════════════════════════════════════════════════

with trim_lookup as (
  select ct.id, cp.phase_label, ct.name
  from catalog_trims ct
  join catalog_phases cp on cp.id = ct.phase_id
  join catalog_models cm on cm.id = cp.model_id
  join catalog_brands cb on cb.id = cm.brand_id
  where cb.name = 'Volkswagen' and cm.name = 'Passat' and cp.generation_code = 'CJ'
)
insert into catalog_trim_features (trim_id, feature, is_optional)
select tl.id, v.feature, v.is_optional
from (
  values
    ('Pre-facelift'::text, 'Passat'::text, '16-inch alloy wheels'::text, false),
    ('Pre-facelift'::text, 'Passat'::text, 'LED headlights'::text, false),
    ('Pre-facelift'::text, 'Passat'::text, '12.9-inch infotainment'::text, false),
    ('Pre-facelift'::text, 'Passat'::text, 'Climatronic 2-zone'::text, false),
    ('Pre-facelift'::text, 'Passat'::text, 'Lane Assist'::text, false),
    ('Pre-facelift'::text, 'Business'::text, '17-inch alloy wheels'::text, false),
    ('Pre-facelift'::text, 'Business'::text, 'ergoActive seats with massage'::text, false),
    ('Pre-facelift'::text, 'Business'::text, '3-zone Climatronic'::text, false),
    ('Pre-facelift'::text, 'Business'::text, 'Voice control'::text, false),
    ('Pre-facelift'::text, 'Elegance'::text, '17-inch alloys'::text, false),
    ('Pre-facelift'::text, 'Elegance'::text, 'IQ.LIGHT matrix LED'::text, false),
    ('Pre-facelift'::text, 'Elegance'::text, 'Acoustic windows'::text, false),
    ('Pre-facelift'::text, 'Elegance'::text, 'Ambient lighting'::text, false),
    ('Pre-facelift'::text, 'Elegance'::text, 'Park assist plus'::text, false),
    ('Pre-facelift'::text, 'R-Line'::text, 'Specific R-Line exterior styling'::text, false),
    ('Pre-facelift'::text, 'R-Line'::text, '18-inch wheels'::text, false),
    ('Pre-facelift'::text, 'R-Line'::text, 'Sports seats'::text, false),
    ('Pre-facelift'::text, 'R-Line'::text, 'Black headliner'::text, false)
) as v(phase_label, trim_name, feature, is_optional)
join trim_lookup tl on tl.phase_label = v.phase_label and tl.name = v.trim_name
where not exists (
  select 1 from catalog_trim_features ctf where ctf.trim_id = tl.id and ctf.feature = v.feature
);

